package com.valor.installation;
import com.valor.auth.*;
import com.valor.notifications.NotificationService;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Page;
import static com.valor.installation.InspectionDtos.*;

@Service @Transactional class InspectionService {
 private final InstallationInspectionRepository inspections; private final InspectionHistoryRepository history; private final InspectionEvidenceRepository evidence; private final InstallationRequestRepository requests; private final AssetIdentityAccess access; private final WorkflowIdentityAccess identities; private final AuditService audit; private final NotificationService notifications;
 InspectionService(InstallationInspectionRepository inspections,InspectionHistoryRepository history,InspectionEvidenceRepository evidence,InstallationRequestRepository requests,AssetIdentityAccess access,WorkflowIdentityAccess identities,AuditService audit,NotificationService notifications){this.inspections=inspections;this.history=history;this.evidence=evidence;this.requests=requests;this.access=access;this.identities=identities;this.audit=audit;this.notifications=notifications;}
 @Transactional(readOnly=true) View customerRead(Long requestId){var c=identities.customer(access.actor());return inspections.findByRequestId(requestId).filter(i->i.getRequest().getCustomer().getId().equals(c.getId())).map(this::customerView).orElseThrow(()->new AccessDeniedException("Access denied"));}
 @Transactional(readOnly=true) View adminRead(Long id){access.requireAdmin();return view(row(id));}
 @Transactional(readOnly=true) View adminReadForInstallation(Long requestId){access.requireAdmin();return inspections.findByRequestId(requestId).map(this::view).orElseThrow(()->new IllegalArgumentException("Inspection not found"));}
 @Transactional(readOnly=true) Page<Summary> adminQueue(InspectionStatus status,Long technicianId,LocalDateTime from,LocalDateTime to,int page,int size){access.requireAdmin();if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid paging");if(from!=null&&to!=null&&!from.isBefore(to))throw new IllegalArgumentException("Invalid scheduled date range");return inspections.search(status,technicianId,from,to,PageRequest.of(page,size)).map(this::summary);}
 @Transactional(readOnly=true) Page<Summary> technicianQueue(InspectionStatus status,int page,int size){var t=identities.technician(access.actor());if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid paging");Page<InstallationInspection> result=inspections.assignedTo(t.getId(),status,PageRequest.of(page,size));return result.map(this::summary);}
 @Transactional(readOnly=true) View technicianRead(Long id){var t=identities.technician(access.actor());return view(inspections.findByIdAndAssignedTechnicianId(id,t.getId()).orElseThrow(()->new AccessDeniedException("Inspection assignment required")));}
 View request(Long requestId){access.requireAdmin();var req=requests.findById(requestId).orElseThrow(()->new IllegalArgumentException("Installation not found"));if(req.getStatus()!=InstallationStatus.SUBMITTED)throw conflict("Only submitted installations can be inspected");if(inspections.findByRequestId(requestId).isPresent())throw conflict("An active inspection already exists");var i=new InstallationInspection();i.setRequest(req);save(i,null,InspectionStatus.REQUESTED,"Inspection requested");audit.record("INSTALLATION_INSPECTION_REQUEST","INSTALLATION_INSPECTION",i.getId(),"Inspection requested");return view(i);}
 View schedule(Long id,ScheduleRequest in){access.requireAdmin();var i=editable(id,in.version());i.setScheduledAt(in.scheduledAt());i.setScheduledTimezone(clean(in.scheduledTimezone()));transition(i,InspectionStatus.SCHEDULED,"Inspection scheduled");save(i);audit.record("INSTALLATION_INSPECTION_SCHEDULE","INSTALLATION_INSPECTION",id,"Inspection scheduled");notifyCustomer(i,"INSPECTION_SCHEDULED","Inspection scheduled","Your site inspection has been scheduled.");return view(i);}
 View assign(Long id,AssignRequest in){access.requireAdmin();var i=editable(id,in.version());i.setAssignedTechnician(identities.activeTechnician(in.technicianProfileId()));transition(i,InspectionStatus.ASSIGNED,"Inspector assigned");save(i);audit.record("INSTALLATION_INSPECTION_ASSIGN","INSTALLATION_INSPECTION",id,"Inspector assigned");return view(i);}
 View reschedule(Long id,RescheduleRequest in){access.requireAdmin();var i=editable(id,in.version());i.setScheduledAt(in.scheduledAt());i.setScheduledTimezone(clean(in.scheduledTimezone()));transition(i,InspectionStatus.RESCHEDULE_REQUIRED,clean(in.reason()));save(i);audit.record("INSTALLATION_INSPECTION_RESCHEDULE","INSTALLATION_INSPECTION",id,"Inspection rescheduled");notifyCustomer(i,"INSPECTION_RESCHEDULED","Inspection rescheduled","Your site inspection appointment was rescheduled.");return view(i);}
 View cancel(Long id,CancelRequest in){access.requireAdmin();var i=editable(id,in.version());transition(i,InspectionStatus.CANCELLED,in.reason());save(i);audit.record("INSTALLATION_INSPECTION_CANCEL","INSTALLATION_INSPECTION",id,"Inspection cancelled");return view(i);}
 View start(Long id){var i=assigned(id);if(i.getStatus()!=InspectionStatus.ASSIGNED&&i.getStatus()!=InspectionStatus.RESCHEDULE_REQUIRED)throw conflict("Inspection cannot be started in this state");i.setVisitStartedAt(LocalDateTime.now());transition(i,InspectionStatus.IN_PROGRESS,"Inspection started");save(i);return view(i);}
 View assess(Long id,AssessmentRequest in){var i=assigned(id);if(i.getStatus()!=InspectionStatus.IN_PROGRESS&&i.getStatus()!=InspectionStatus.REWORK_REQUIRED)throw conflict("Inspection assessment cannot be edited in this state");i.setConclusion(clean(in.conclusion()));i.setMeasurements(in.measurements());i.setFindings(in.findings());i.setSiteConstraints(in.siteConstraints());i.setReadinessObservations(in.readinessObservations());i.setIssues(in.issues());i.setRisks(in.risks());i.setRecommendedActions(in.recommendedActions());i.setSubmittedAt(LocalDateTime.now());transition(i,InspectionStatus.SUBMITTED,"Assessment submitted");save(i);audit.record("INSTALLATION_INSPECTION_SUBMIT","INSTALLATION_INSPECTION",id,"Assessment submitted");return view(i);}
 View review(Long id,ReviewRequest in){access.requireAdmin();var i=editable(id,in.version());if(i.getStatus()!=InspectionStatus.SUBMITTED)throw conflict("Only submitted assessments can be reviewed");InspectionStatus next="APPROVED".equals(in.decision())?InspectionStatus.APPROVED:InspectionStatus.REWORK_REQUIRED;i.setReviewer(access.actor());i.setReviewNotes(in.notes());i.setReviewedAt(LocalDateTime.now());transition(i,next,in.notes());save(i);audit.record("INSTALLATION_INSPECTION_REVIEW","INSTALLATION_INSPECTION",id,"Inspection assessment reviewed");notifyCustomer(i,next==InspectionStatus.APPROVED?"INSPECTION_APPROVED":"INSPECTION_REWORK_REQUIRED",next==InspectionStatus.APPROVED?"Inspection approved":"Inspection needs rework",next==InspectionStatus.APPROVED?"Your site inspection was approved. Valor will provide the next supported step when available.":"Your site inspection was returned for rework. Please wait for an updated appointment or instructions.");return view(i);}
 View addEvidence(Long id,EvidenceRequest in){var i=assigned(id);if(i.getStatus()!=InspectionStatus.IN_PROGRESS&&i.getStatus()!=InspectionStatus.REWORK_REQUIRED)throw conflict("Evidence cannot be added in this state");var e=new InstallationInspectionEvidence();e.setInspection(i);e.setReferencedBy(access.actor());e.setDocumentType(in.documentType().trim());e.setOriginalFilename(in.originalFilename().trim());e.setContentType(in.contentType().trim());e.setStorageKey(in.storageKey().trim());evidence.saveAndFlush(e);return view(i);}
 private InstallationInspection assigned(Long id){var t=identities.technician(access.actor());return inspections.findByIdAndAssignedTechnicianId(id,t.getId()).orElseThrow(()->new AccessDeniedException("Inspection assignment required"));}
 private InstallationInspection editable(Long id,Long version){var i=row(id);if(version==null||!version.equals(i.getVersion()))throw conflict("Inspection changed; refresh and try again");if(i.getStatus()==InspectionStatus.CANCELLED||i.getStatus()==InspectionStatus.APPROVED)throw conflict("Inspection cannot be changed in this state");return i;}
 private InstallationInspection row(Long id){return inspections.findById(id).orElseThrow(()->new IllegalArgumentException("Inspection not found"));}
 private void transition(InstallationInspection i,InspectionStatus to,String notes){InspectionStatus from=i.getStatus();i.setStatus(to);var h=new InstallationInspectionHistory();h.setInspection(i);h.setChangedBy(access.actor());h.setFromStatus(from);h.setToStatus(to);h.setNotes(notes);history.save(h);}
 private void save(InstallationInspection i){inspections.saveAndFlush(i);} private void save(InstallationInspection i,InspectionStatus from,InspectionStatus to,String notes){i.setStatus(to);inspections.saveAndFlush(i);var h=new InstallationInspectionHistory();h.setInspection(i);h.setChangedBy(access.actor());h.setFromStatus(from);h.setToStatus(to);h.setNotes(notes);history.saveAndFlush(h);}
 private View view(InstallationInspection i){return new View(i.getId(),i.getRequest().getId(),i.getStatus(),i.getScheduledAt(),i.getScheduledTimezone(),i.getAssignedTechnician()==null?null:i.getAssignedTechnician().getId(),i.getVisitStartedAt(),i.getSubmittedAt(),i.getConclusion(),i.getMeasurements(),i.getFindings(),i.getSiteConstraints(),i.getReadinessObservations(),i.getIssues(),i.getRisks(),i.getRecommendedActions(),i.getReviewer()==null?null:i.getReviewer().getId(),i.getReviewNotes(),i.getReviewedAt(),i.getVersion(),history.findByInspectionIdOrderByChangedAtAscIdAsc(i.getId()).stream().map(h->new History(h.getId(),h.getFromStatus(),h.getToStatus(),h.getNotes(),h.getChangedAt(),h.getChangedBy().getId())).toList(),evidence.findByInspectionIdOrderByCreatedAtAscIdAsc(i.getId()).stream().map(e->new Evidence(e.getId(),e.getDocumentType(),e.getOriginalFilename(),e.getContentType(),e.getStorageKey(),e.getCreatedAt())).toList());}
 private View customerView(InstallationInspection i){var full=view(i);return new View(full.id(),full.installationRequestId(),full.status(),full.scheduledAt(),full.scheduledTimezone(),null,full.visitStartedAt(),full.submittedAt(),full.conclusion(),full.measurements(),full.findings(),full.siteConstraints(),full.readinessObservations(),full.issues(),full.risks(),full.recommendedActions(),null,null,full.reviewedAt(),full.version(),full.history(),List.of());}
 private Summary summary(InstallationInspection i){var r=i.getRequest();return new Summary(i.getId(),r.getId(),i.getStatus(),i.getScheduledAt(),i.getScheduledTimezone(),i.getAssignedTechnician()==null?null:i.getAssignedTechnician().getId(),i.getVisitStartedAt(),i.getSubmittedAt(),r.getPropertyType(),r.getSiteAddressLine1(),r.getSiteAddressLine2(),r.getSiteLocality(),r.getSiteCity(),r.getSiteState(),r.getSitePostalCode(),r.getSiteCountry(),r.getSitePropertyDescription(),i.getVersion());}
 private void notifyCustomer(InstallationInspection i,String type,String title,String message){notifications.createSystemOnce(i.getRequest().getCustomer().getUser().getId(),type+":"+i.getId()+":"+i.getVersion(),title,message);}
 private static String clean(String v){return v==null||v.isBlank()?null:v.trim();} private static IllegalStateException conflict(String m){return new IllegalStateException(m);}
}
